#!/usr/bin/env python3
"""
Round 99b tiles patch (28 September 2026), beside round99b_culprits.py.

  scripts/ifl.py           new: the Intact Forest Landscapes of 2000, 2013,
                           2016, 2020 and 2025 as the map's own copies, from
                           Global Forest Watch's tables (tiles/ifl_<year>.pmtiles).
  scripts/ecoregions.py    new: RESOLVE's Ecoregions 2017 as the map's own copy
                           (tiles/ecoregions_2017.pmtiles).
  scripts/critical_habitat.py  the classes named from the paper: 1 potential,
                           10 likely critical habitat (Dunnett et al. 2025).
  scripts/soil_biodiversity.py  its list of maps held NaN, which is not JSON,
                           so the map said "not built yet"; now null, and each
                           map named plainly, the hotspots first.
  tiles/own_critical_habitat.choices.json, soil/spun_choices.json  the two
                           files as they are now, mended the same way, so the
                           map reads them without waiting for a build.

Whole files, written only where they differ. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/critical_habitat.py': '', 'scripts/soil_biodiversity.py': '', 'scripts/ifl.py': '', 'scripts/ecoregions.py': '', 'tiles/own_critical_habitat.choices.json': '', 'soil/spun_choices.json': ''}

changed = []
for path, b64 in FILES.items():
    p = pathlib.Path(path)
    new = base64.b64decode(b64)
    if not p.parent.exists():
        raise SystemExit(f"round99b: {p.parent} not found; run from the culprits-tiles-more root")
    if p.exists() and p.read_bytes() == new:
        continue
    p.write_bytes(new)
    changed.append(path)
print("round99b: " + (", ".join(changed) if changed else "nothing to change (already applied)"))
